settings.custom_liquid:
{% assign main_handle = 'aliviax-pro' %}
{% assign main_product = all_products[main_handle] %}

{% assign suggestion_1 = all_products['aliviax-pro'] %}
{% assign suggestion_2 = all_products['aliviax-corrector-de-postura'] %}
{% assign suggestion_3 = all_products['aliviax-banda-termica'] %}

<section class="ax-cart-shell">
  <div class="page-width">

    {% if cart.item_count > 0 %}
      <div class="ax-cart-head">
        <div>
          <span class="ax-cart-head__eyebrow">AliviaX</span>
          <h1 class="ax-cart-head__title">Tu carrito está casi listo</h1>
          <p class="ax-cart-head__text">
            Revisa tu pedido y descubre productos recomendados para complementar tu compra.
          </p>
        </div>

        <div class="ax-cart-head__pill">
          {{ cart.item_count }} producto{% if cart.item_count != 1 %}s{% endif %}
        </div>
      </div>

      {% assign available_suggestions = 0 %}

      {% assign s1_in_cart = false %}
      {% if suggestion_1 != blank %}
        {% for item in cart.items %}
          {% if item.product.handle == suggestion_1.handle %}
            {% assign s1_in_cart = true %}
          {% endif %}
        {% endfor %}
        {% if s1_in_cart == false %}
          {% assign available_suggestions = available_suggestions | plus: 1 %}
        {% endif %}
      {% endif %}

      {% assign s2_in_cart = false %}
      {% if suggestion_2 != blank %}
        {% for item in cart.items %}
          {% if item.product.handle == suggestion_2.handle %}
            {% assign s2_in_cart = true %}
          {% endif %}
        {% endfor %}
        {% if s2_in_cart == false %}
          {% assign available_suggestions = available_suggestions | plus: 1 %}
        {% endif %}
      {% endif %}

      {% assign s3_in_cart = false %}
      {% if suggestion_3 != blank %}
        {% for item in cart.items %}
          {% if item.product.handle == suggestion_3.handle %}
            {% assign s3_in_cart = true %}
          {% endif %}
        {% endfor %}
        {% if s3_in_cart == false %}
          {% assign available_suggestions = available_suggestions | plus: 1 %}
        {% endif %}
      {% endif %}

      <div class="ax-cart-layout">
        <form action="{{ routes.cart_url }}" method="post" novalidate class="ax-cart-form">
          <div class="ax-cart-main">
            {% for item in cart.items %}
              <article class="ax-line" style="--delay: {{ forloop.index0 | times: 90 }}ms;">
                <a href="{{ item.url }}" class="ax-line__media">
                  {% if item.image %}
                    <img
                      src="{{ item.image | image_url: width: 320 }}"
                      alt="{{ item.image.alt | escape }}"
                      width="136"
                      height="136"
                      loading="lazy"
                      class="ax-line__image"
                    >
                  {% endif %}
                </a>

                <div class="ax-line__content">
                  <div class="ax-line__inner">
                    <div class="ax-line__topbar">
                      <span class="ax-line__tag">Producto</span>

                      <a href="{{ item.url_to_remove }}" class="ax-line__remove">
                        Eliminar
                      </a>
                    </div>

                    <div class="ax-line__grid">
                      <div class="ax-line__info">
                        <a href="{{ item.url }}" class="ax-line__title">
                          {{ item.product.title }}
                        </a>

                        {% unless item.variant.title == 'Default Title' %}
                          <p class="ax-line__variant">{{ item.variant.title }}</p>
                        {% else %}
                          <p class="ax-line__variant">Configuración estándar</p>
                        {% endunless %}

                        {% if item.properties.size > 0 %}
                          <ul class="ax-line__props">
                            {% for property in item.properties %}
                              {% assign first_char = property.first | slice: 0 %}
                              {% if property.last != blank and first_char != '_' %}
                                <li><strong>{{ property.first }}:</strong> {{ property.last }}</li>
                              {% endif %}
                            {% endfor %}
                          </ul>
                        {% endif %}

                        <div class="ax-line__price">
                          {% if item.original_line_price != item.final_line_price %}
                            <span class="ax-line__price-old">{{ item.original_line_price | money }}</span>
                            <strong>{{ item.final_line_price | money }}</strong>
                          {% else %}
                            <strong>{{ item.original_line_price | money }}</strong>
                          {% endif %}
                        </div>
                      </div>

                      <div class="ax-line__actions">
                        <div class="ax-line__qtybox">
                          <span class="ax-line__qtytext">Cantidad</span>
                          <input
                            id="updates_{{ item.key }}"
                            type="number"
                            name="updates[]"
                            value="{{ item.quantity }}"
                            min="0"
                            data-line="{{ forloop.index }}"
                            class="ax-line__qtyinput"
                          >
                        </div>
                      </div>
                    </div>
                  </div>
                </div>
              </article>
            {% endfor %}
          </div>

          <aside class="ax-cart-side">
            <div class="ax-summary">
              <h2>Resumen</h2>

              <div class="ax-summary__row">
                <span>Subtotal</span>
                <strong id="ax-cart-subtotal">{{ cart.total_price | money }}</strong>
              </div>

              <p class="ax-summary__note">
                Envío y descuentos calculados al finalizar la compra.
              </p>

              <div class="ax-summary__badges">
                <span>Pago seguro</span>
                <span>Envío rápido</span>
                <span>Compra protegida</span>
              </div>

              <div class="ax-summary__buttons">
                <button type="submit" name="checkout" class="ax-btn ax-btn--primary">
                  Finalizar compra
                </button>
              </div>
            </div>
          </aside>
        </form>

        {% if available_suggestions > 0 %}
          <div class="ax-suggestions-wrap">
            <div class="ax-suggestions">
              <div class="ax-suggestions__head">
                <span class="ax-suggestions__eyebrow">Sugerencias</span>
                <h2>También puede gustarte</h2>
              </div>

              <div class="ax-suggestions__grid">
                {% if suggestion_1 != blank and s1_in_cart == false %}
                  {% assign suggested_variant = suggestion_1.selected_or_first_available_variant %}
                  <div class="ax-suggestion-card">
                    <a href="{{ suggestion_1.url }}" class="ax-suggestion-card__media">
                      {% if suggestion_1.featured_image %}
                        <img
                          src="{{ suggestion_1.featured_image | image_url: width: 420 }}"
                          alt="{{ suggestion_1.title | escape }}"
                          width="420"
                          height="420"
                          loading="lazy"
                          class="ax-suggestion-card__image"
                        >
                      {% endif %}
                    </a>
                    <div class="ax-suggestion-card__content">
                      <a href="{{ suggestion_1.url }}" class="ax-suggestion-card__title">
                        {{ suggestion_1.title }}
                      </a>
                      <div class="ax-suggestion-card__price">
                        {% if suggestion_1.compare_at_price > suggestion_1.price %}
                          <span class="ax-suggestion-card__price-old">{{ suggestion_1.compare_at_price | money }}</span>
                        {% endif %}
                        <strong>{{ suggestion_1.price | money }}</strong>
                      </div>

                      {% if suggested_variant != blank and suggestion_1.available %}
                        <form method="post" action="/cart/add" class="ax-add-form">
                          <input type="hidden" name="id" value="{{ suggested_variant.id }}">
                          <input type="hidden" name="quantity" value="1">
                          <button type="submit" class="ax-btn ax-btn--primary ax-btn--full">Añadir</button>
                        </form>
                      {% else %}
                        <a href="{{ suggestion_1.url }}" class="ax-btn ax-btn--ghost ax-btn--full">
                          Ver producto
                        </a>
                      {% endif %}
                    </div>
                  </div>
                {% endif %}

                {% if suggestion_2 != blank and s2_in_cart == false %}
                  {% assign suggested_variant = suggestion_2.selected_or_first_available_variant %}
                  <div class="ax-suggestion-card">
                    <a href="{{ suggestion_2.url }}" class="ax-suggestion-card__media">
                      {% if suggestion_2.featured_image %}
                        <img
                          src="{{ suggestion_2.featured_image | image_url: width: 420 }}"
                          alt="{{ suggestion_2.title | escape }}"
                          width="420"
                          height="420"
                          loading="lazy"
                          class="ax-suggestion-card__image"
                        >
                      {% endif %}
                    </a>
                    <div class="ax-suggestion-card__content">
                      <a href="{{ suggestion_2.url }}" class="ax-suggestion-card__title">
                        {{ suggestion_2.title }}
                      </a>
                      <div class="ax-suggestion-card__price">
                        {% if suggestion_2.compare_at_price > suggestion_2.price %}
                          <span class="ax-suggestion-card__price-old">{{ suggestion_2.compare_at_price | money }}</span>
                        {% endif %}
                        <strong>{{ suggestion_2.price | money }}</strong>
                      </div>

                      {% if suggested_variant != blank and suggestion_2.available %}
                        <form method="post" action="/cart/add" class="ax-add-form">
                          <input type="hidden" name="id" value="{{ suggested_variant.id }}">
                          <input type="hidden" name="quantity" value="1">
                          <button type="submit" class="ax-btn ax-btn--primary ax-btn--full">Añadir</button>
                        </form>
                      {% else %}
                        <a href="{{ suggestion_2.url }}" class="ax-btn ax-btn--ghost ax-btn--full">
                          Ver producto
                        </a>
                      {% endif %}
                    </div>
                  </div>
                {% endif %}

                {% if suggestion_3 != blank and s3_in_cart == false %}
                  {% assign suggested_variant = suggestion_3.selected_or_first_available_variant %}
                  <div class="ax-suggestion-card">
                    <a href="{{ suggestion_3.url }}" class="ax-suggestion-card__media">
                      {% if suggestion_3.featured_image %}
                        <img
                          src="{{ suggestion_3.featured_image | image_url: width: 420 }}"
                          alt="{{ suggestion_3.title | escape }}"
                          width="420"
                          height="420"
                          loading="lazy"
                          class="ax-suggestion-card__image"
                        >
                      {% endif %}
                    </a>
                    <div class="ax-suggestion-card__content">
                      <a href="{{ suggestion_3.url }}" class="ax-suggestion-card__title">
                        {{ suggestion_3.title }}
                      </a>
                      <div class="ax-suggestion-card__price">
                        {% if suggestion_3.compare_at_price > suggestion_3.price %}
                          <span class="ax-suggestion-card__price-old">{{ suggestion_3.compare_at_price | money }}</span>
                        {% endif %}
                        <strong>{{ suggestion_3.price | money }}</strong>
                      </div>

                      {% if suggested_variant != blank and suggestion_3.available %}
                        <form method="post" action="/cart/add" class="ax-add-form">
                          <input type="hidden" name="id" value="{{ suggested_variant.id }}">
                          <input type="hidden" name="quantity" value="1">
                          <button type="submit" class="ax-btn ax-btn--primary ax-btn--full">Añadir</button>
                        </form>
                      {% else %}
                        <a href="{{ suggestion_3.url }}" class="ax-btn ax-btn--ghost ax-btn--full">
                          Ver producto
                        </a>
                      {% endif %}
                    </div>
                  </div>
                {% endif %}
              </div>
            </div>
          </div>
        {% endif %}
      </div>

    {% else %}
      <div class="ax-cart-empty">
        <span class="ax-cart-empty__eyebrow">AliviaX</span>
        <h1>Tu carrito está vacío</h1>
        <p>
          Empieza con nuestro producto principal y añade tu AliviaX Pro en un clic.
        </p>

        {% if main_product != blank %}
          {% assign main_variant = main_product.selected_or_first_available_variant %}

          <div class="ax-empty-main">
            <a href="{{ main_product.url }}" class="ax-empty-main__media">
              {% if main_product.featured_image %}
                <img
                  src="{{ main_product.featured_image | image_url: width: 700 }}"
                  alt="{{ main_product.title | escape }}"
                  width="700"
                  height="700"
                  loading="lazy"
                  class="ax-empty-main__image"
                >
              {% endif %}
            </a>

            <div class="ax-empty-main__content">
              <span class="ax-empty-main__badge">Producto principal</span>

              <a href="{{ main_product.url }}" class="ax-empty-main__title">
                {{ main_product.title }}
              </a>

              <div class="ax-empty-main__price">
                {% if main_product.compare_at_price > main_product.price %}
                  <span class="ax-empty-main__price-old">{{ main_product.compare_at_price | money }}</span>
                {% endif %}
                <strong>{{ main_product.price | money }}</strong>
              </div>

              <div class="ax-cart-empty__actions">
                <a href="{{ main_product.url }}" class="ax-btn ax-btn--ghost">
                  Ver producto
                </a>

                {% if main_variant != blank and main_product.available %}
                  <form method="post" action="/cart/add" class="ax-add-form">
                    <input type="hidden" name="id" value="{{ main_variant.id }}">
                    <input type="hidden" name="quantity" value="1">
                    <button type="submit" class="ax-btn ax-btn--primary">
                      Añadir al carrito
                    </button>
                  </form>
                {% endif %}
              </div>
            </div>
          </div>
        {% endif %}
      </div>
    {% endif %}
  </div>

  <style>
    .ax-cart-shell {
      --ax-bg: #f9fcfb;
      --ax-bg-2: #f4f8f7;
      --ax-surface: rgba(255,255,255,.96);
      --ax-surface-soft: rgba(255,255,255,.76);
      --ax-text: #0d2640;
      --ax-muted: #5a6c7e;
      --ax-line: rgba(13,38,64,.08);
      --ax-primary: #0d9977;
      --ax-primary-2: #0dbd90;
      --ax-primary-soft: #e5f5ef;
      --ax-danger-soft: #fef0f2;
      --ax-radius: 30px;
      --ax-shadow: 0 18px 50px rgba(13,38,64,.07);
      padding: 54px 0 88px;
      background:
        radial-gradient(circle at 14% 10%, rgba(13,153,119,.06), transparent 0 24%),
        radial-gradient(circle at 85% 8%, rgba(13,38,64,.06), transparent 0 20%),
        linear-gradient(180deg, var(--ax-bg-2) 0%, var(--ax-bg) 100%);
      color: var(--ax-text);
    }

    .ax-cart-shell .page-width {
      max-width: 1280px;
      margin: 0 auto;
      padding: 0 24px;
    }

    .ax-cart-head {
      display: grid;
      grid-template-columns: minmax(0, 1fr) auto;
      gap: 28px;
      align-items: end;
      margin-bottom: 34px;
    }

    .ax-cart-head__eyebrow,
    .ax-cart-empty__eyebrow,
    .ax-suggestions__eyebrow,
    .ax-empty-main__badge,
    .ax-line__tag {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      min-height: 36px;
      padding: 0 14px;
      border-radius: 999px;
      background: rgba(13,153,119,.08);
      color: var(--ax-primary);
      border: 1px solid rgba(13,153,119,.06);
      font-size: 12px;
      font-weight: 800;
      letter-spacing: .1em;
      text-transform: uppercase;
    }

    .ax-cart-head__title,
    .ax-cart-empty h1 {
      margin: 12px 0 10px;
      font-size: clamp(2.6rem, 4.2vw, 4.8rem);
      line-height: .98;
      letter-spacing: -.065em;
      max-width: 12ch;
      color: #0d2640;
    }

    .ax-cart-head__text,
    .ax-cart-empty p {
      margin: 0;
      max-width: 56ch;
      color: var(--ax-muted);
      line-height: 1.75;
      font-size: 1.02rem;
    }

    .ax-cart-head__pill {
      display: inline-flex;
      align-items: center;
      min-height: 52px;
      padding: 0 20px;
      border-radius: 999px;
      background: rgba(255,255,255,.8);
      border: 1px solid rgba(13,38,64,.08);
      white-space: nowrap;
      font-weight: 800;
      color: var(--ax-text);
    }

    .ax-cart-layout {
      display: grid;
      grid-template-columns: minmax(0, 1.58fr) minmax(320px, .82fr);
      gap: 28px;
      align-items: start;
    }

    .ax-cart-form {
      display: contents;
    }

    .ax-cart-main,
    .ax-summary,
    .ax-suggestions,
    .ax-empty-main,
    .ax-cart-empty {
      background: var(--ax-surface);
      backdrop-filter: blur(18px);
      border: 1px solid rgba(255,255,255,.9);
      box-shadow: var(--ax-shadow);
      border-radius: var(--ax-radius);
    }

    .ax-cart-main {
      overflow: hidden;
      padding: 8px;
    }

    .ax-line {
      display: grid;
      grid-template-columns: 136px 1fr;
      gap: 18px;
      padding: 14px;
      border-radius: 24px;
      align-items: stretch;
    }

    .ax-line + .ax-line {
      margin-top: 10px;
    }

    .ax-line__media {
      display: block;
      border-radius: 24px;
      overflow: hidden;
      background: #f2f7f5;
      align-self: stretch;
    }

    .ax-line__image {
      width: 136px;
      height: 136px;
      object-fit: cover;
      border-radius: 24px;
      background: #edf5f3;
      transition: transform .45s cubic-bezier(.16,1,.3,1);
      box-shadow: none;
      filter: none;
    }

    .ax-line:hover .ax-line__image,
    .ax-suggestion-card:hover .ax-suggestion-card__image,
    .ax-empty-main:hover .ax-empty-main__image {
      transform: scale(1.025);
    }

    .ax-line__content {
      display: flex;
      flex-direction: column;
      justify-content: stretch;
      min-width: 0;
    }

    .ax-line__inner {
      display: grid;
      gap: 14px;
      background: rgba(255,255,255,.76);
      border: 1px solid rgba(13,38,64,.07);
      border-radius: 24px;
      padding: 16px 18px;
      min-height: 136px;
    }

    .ax-line__topbar {
      display: flex;
      justify-content: space-between;
      align-items: center;
      gap: 12px;
      padding-bottom: 10px;
      border-bottom: 1px solid var(--ax-line);
    }

    .ax-line__tag {
      min-height: 30px;
      padding: 0 10px;
      font-size: 11px;
      letter-spacing: .08em;
    }

    .ax-line__grid {
      display: grid;
      grid-template-columns: minmax(0, 1fr) auto;
      gap: 20px;
      align-items: center;
    }

    .ax-line__info {
      display: grid;
      gap: 6px;
      align-content: start;
      min-width: 0;
    }

    .ax-line__actions {
      display: grid;
      justify-items: end;
      align-content: center;
      min-width: 120px;
    }

    .ax-line__title,
    .ax-suggestion-card__title,
    .ax-empty-main__title {
      color: var(--ax-text);
      text-decoration: none;
      font-weight: 800;
      letter-spacing: -.03em;
    }

    .ax-line__title {
      font-size: 1.14rem;
      line-height: 1.2;
      margin: 0;
      max-width: 26ch;
    }

    .ax-line__title:hover,
    .ax-suggestion-card__title:hover,
    .ax-empty-main__title:hover {
      color: var(--ax-primary);
    }

    .ax-line__variant,
    .ax-line__props {
      color: var(--ax-muted);
      font-size: 14px;
    }

    .ax-line__variant {
      margin: 0;
      line-height: 1.4;
      font-weight: 600;
    }

    .ax-line__props {
      list-style: none;
      margin: 0;
      padding: 0;
    }

    .ax-line__props li + li {
      margin-top: 4px;
    }

    .ax-line__price,
    .ax-suggestion-card__price,
    .ax-empty-main__price {
      display: flex;
      align-items: center;
      gap: 10px;
      flex-wrap: wrap;
      color: var(--ax-primary);
    }

    .ax-line__price {
      margin-top: 4px;
    }

    .ax-line__price-old,
    .ax-suggestion-card__price-old,
    .ax-empty-main__price-old {
      text-decoration: line-through;
      color: #8ea19c;
      font-size: 14px;
    }

    .ax-line__price strong {
      font-size: 1.22rem;
      line-height: 1;
      letter-spacing: -.03em;
    }

    .ax-line__remove {
      text-decoration: none;
      white-space: nowrap;
      font-weight: 700;
      font-size: 13px;
      color: #8c5d67;
      background: var(--ax-danger-soft);
      border: 1px solid rgba(182,57,77,.08);
      padding: 9px 12px;
      border-radius: 999px;
    }

    .ax-line__remove:hover {
      color: #b6394d;
      background: #fff1f3;
    }

    .ax-line__qtybox {
      display: grid;
      gap: 8px;
      justify-items: end;
      padding: 12px 12px 12px 14px;
      border-radius: 18px;
      background: var(--ax-primary-soft);
      border: 1px solid rgba(13,38,64,.06);
      min-width: 120px;
    }

    .ax-line__qtytext {
      font-size: 12px;
      font-weight: 800;
      letter-spacing: .08em;
      text-transform: uppercase;
      color: var(--ax-primary);
    }

    .ax-line__qtyinput {
      border: 1px solid rgba(13,38,64,.10);
      background: rgba(255,255,255,.96);
      border-radius: 14px;
      width: 74px;
      height: 42px;
      padding: 0 10px;
      text-align: center;
      font-size: 16px;
      font-weight: 700;
      color: var(--ax-text);
      box-shadow: none;
      transition: .25s ease;
    }

    .ax-line__qtyinput:focus {
      outline: none;
      border-color: rgba(13,153,119,.42);
      box-shadow: 0 0 0 5px rgba(13,153,119,.12);
    }

    .ax-cart-side {
      display: grid;
      gap: 18px;
      align-self: start;
      position: sticky;
      top: 24px;
    }

    .ax-summary,
    .ax-suggestions {
      padding: 24px;
      border-radius: 28px;
    }

    .ax-summary {
      background: linear-gradient(180deg, rgba(255,255,255,.96) 0%, rgba(247,251,249,.94) 100%);
    }

    .ax-summary h2,
    .ax-suggestions h2 {
      margin: 4px 0 16px;
      font-size: 1.75rem;
      letter-spacing: -.04em;
      color: #0d2640;
    }

    .ax-summary__row {
      display: flex;
      justify-content: space-between;
      align-items: center;
      gap: 14px;
      font-size: 1.08rem;
      margin-bottom: 14px;
      padding-bottom: 14px;
      border-bottom: 1px solid var(--ax-line);
    }

    .ax-summary__row strong {
      font-size: 1.28rem;
      color: var(--ax-primary);
      letter-spacing: -.03em;
    }

    .ax-summary__note {
      margin: 0 0 18px;
      color: var(--ax-muted);
      font-size: 14px;
      line-height: 1.65;
    }

    .ax-summary__badges {
      display: flex;
      flex-wrap: wrap;
      gap: 8px;
      margin-bottom: 20px;
    }

    .ax-summary__badges span {
      display: inline-flex;
      align-items: center;
      min-height: 34px;
      padding: 0 12px;
      border-radius: 999px;
      background: var(--ax-primary-soft);
      color: var(--ax-primary);
      font-size: 13px;
      font-weight: 700;
      border: 1px solid rgba(13,38,64,.06);
    }

    .ax-summary__buttons {
      display: grid;
      gap: 12px;
      margin-top: 10px;
    }

    .ax-suggestions-wrap {
      margin-top: 26px;
      margin-bottom: 84px;
      align-self: start;
    }

    .ax-suggestions {
      background: linear-gradient(180deg, rgba(255,255,255,.94) 0%, rgba(247,251,249,.92) 100%);
    }

    .ax-suggestions__head {
      text-align: center;
      margin-bottom: 18px;
    }

