  <script>
    document.addEventListener('DOMContentLoaded', () => {
      const qtyInputs = document.querySelectorAll('.ax-line__qtyinput');
      const subtotalEl = document.querySelector('#ax-cart-subtotal');
      const pillEl = document.querySelector('.ax-cart-head__pill');

      const formatMoney = (cents) => {
        return new Intl.NumberFormat('es-ES', {
          style: 'currency', 
          currency: '{{ cart.currency.iso_code | default: shop.currency }}'
        }).format(cents / 100);
      };

      qtyInputs.forEach((input) => {
        input.addEventListener('change', async () => {
          const line = input.dataset.line;
          const quantity = parseInt(input.value, 10);

          if (isNaN(quantity) || quantity < 0) {
            input.value = 1;
            return;
          }

          try {
            const response = await fetch('/cart/change.js', {
              method: 'POST',
              headers: {
                'Content-Type': 'application/json',
                'Accept': 'application/json'
              },
              body: JSON.stringify({
                line: Number(line),
                quantity: quantity
              })
            });

            if (!response.ok) {
              throw new Error('Error en el carrito');
            }

            const cart = await response.json();

            if (subtotalEl) {
              subtotalEl.textContent = formatMoney(cart.total_price);
            }

            if (pillEl && cart.item_count > 0) {
              pillEl.textContent = cart.item_count + ' producto' + (cart.item_count != 1 ? 's' : '');
            }

            if (quantity === 0) {
              window.location.reload();
            }
          } catch (error) {
            console.error('Error actualizando carrito:', error);
            window.location.reload();
          }
        });
      });
    });
  </script>
